import React from "react";
import { motion } from "framer-motion";

export default function Feedback() {
  return (
    <div className="bg-gray-50 min-h-screen flex items-center justify-center px-4 py-12">
      <motion.div
        initial={{ opacity: 0, y: 30 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
        className="bg-white rounded-2xl shadow-lg p-10 max-w-lg w-full border border-gray-100"
      >
        <h2 className="text-3xl font-bold text-blue-600 mb-4 text-center">
          AI Feedback Report
        </h2>
        <p className="text-gray-600 text-center mb-6">
          Review detailed analysis of your performance and get improvement tips.
        </p>

        <textarea
          placeholder="Write your feedback or questions..."
          className="w-full border rounded-lg p-3 h-32 focus:ring-2 focus:ring-blue-400 outline-none"
        />

        <div className="flex justify-center mt-5">
          <motion.button
            whileHover={{ scale: 1.05 }}
            className="px-6 py-3 bg-blue-600 text-white rounded-lg shadow-md hover:bg-blue-700 transition"
          >
            Submit Feedback
          </motion.button>
        </div>
      </motion.div>
    </div>
  );
}
